"""CPA worklist algorithm and explicit-value analysis."""

from __future__ import annotations

import time
from collections import defaultdict, deque
from dataclasses import dataclass
from itertools import product
from typing import Iterable

from cpachecker.cfa import CFA, CFAEdge, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.expression import evaluate_condition, evaluate_expression
from cpachecker.result import Verdict, VerificationResult


class TrivialPrecision(Precision):
    """Single precision object used by the simplified analyses."""


TRIVIAL_PRECISION = TrivialPrecision()


@dataclass(frozen=True)
class LocationState(AbstractState):
    """Abstract state storing the current CFA node."""

    node_id: int


class LocationDomain(AbstractDomain):
    def is_less_or_equal(self, state1: LocationState, state2: LocationState) -> bool:
        return state1 == state2

    def join(self, state1: LocationState, state2: LocationState) -> LocationState:
        return state1 if state1 == state2 else state2

    def get_top(self) -> LocationState:
        return LocationState(-1)

    def get_bottom(self) -> LocationState:
        return LocationState(-2)


class LocationTransferRelation(TransferRelation):
    def get_abstract_successors(
        self, state: LocationState, precision: Precision, edge: CFAEdge
    ) -> list[LocationState]:
        del state, precision
        return [LocationState(edge.target)]


class SepMergeOperator(MergeOperator):
    def merge(
        self, state1: AbstractState, state2: AbstractState, precision: Precision
    ) -> AbstractState:
        del state1, precision
        return state2


class ExactStopOperator(StopOperator):
    def __init__(self, domain: AbstractDomain):
        self._domain = domain

    def stop(
        self, state: AbstractState, reached: set[AbstractState], precision: Precision
    ) -> bool:
        del precision
        return any(self._domain.is_less_or_equal(state, other) for other in reached)


class LocationCPA(ConfigurableProgramAnalysis):
    """CPA component tracking the current CFA node."""

    def __init__(self):
        self._domain = LocationDomain()
        self._transfer = LocationTransferRelation()
        self._merge = SepMergeOperator()
        self._stop = ExactStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> LocationState:
        return LocationState(node_id)

    def get_initial_precision(self) -> Precision:
        return TRIVIAL_PRECISION


@dataclass(frozen=True)
class ExplicitValueState(AbstractState):
    """Explicit mapping for known integer values. Missing entries are TOP."""

    values: tuple[tuple[str, int], ...] = ()

    @property
    def env(self) -> dict[str, int]:
        return dict(self.values)

    def lookup(self, variable: str) -> int | None:
        return self.env.get(variable)

    def assign(self, variable: str, value: int | None) -> "ExplicitValueState":
        env = self.env
        if value is None:
            env.pop(variable, None)
        else:
            env[variable] = int(value)
        return ExplicitValueState(tuple(sorted(env.items())))

    def retain(self, variables: Iterable[str]) -> "ExplicitValueState":
        env = self.env
        filtered = {var: env[var] for var in variables if var in env}
        return ExplicitValueState(tuple(sorted(filtered.items())))

    def __repr__(self) -> str:
        items = ", ".join(f"{key}={value}" for key, value in self.values)
        return f"ExplicitValueState({{{items}}})"


class ExplicitValueDomain(AbstractDomain):
    def is_less_or_equal(
        self, state1: ExplicitValueState, state2: ExplicitValueState
    ) -> bool:
        env1 = state1.env
        env2 = state2.env
        return all(env1.get(var) == value for var, value in env2.items())

    def join(
        self, state1: ExplicitValueState, state2: ExplicitValueState
    ) -> ExplicitValueState:
        env1 = state1.env
        env2 = state2.env
        shared = {
            var: env1[var]
            for var in env1.keys() & env2.keys()
            if env1[var] == env2[var]
        }
        return ExplicitValueState(tuple(sorted(shared.items())))

    def get_top(self) -> ExplicitValueState:
        return ExplicitValueState()

    def get_bottom(self) -> ExplicitValueState:
        return ExplicitValueState((("__bottom__", 0),))


class ExplicitValueTransferRelation(TransferRelation):
    def get_abstract_successors(
        self, state: ExplicitValueState, precision: Precision, edge: CFAEdge
    ) -> list[ExplicitValueState]:
        del precision
        env = state.env

        if edge.edge_type == EdgeType.ASSIGNMENT:
            value = evaluate_expression(edge.expression, env)
            return [state.assign(edge.variable, value)]

        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            condition = evaluate_condition(edge.expression, env)
            if condition is None:
                return [state]
            expected = edge.edge_type == EdgeType.ASSUME_TRUE
            return [state] if condition == expected else []

        if edge.edge_type in (EdgeType.BLANK, EdgeType.FUNCTION_CALL, EdgeType.ASSERT):
            return [state]

        return [state]


class ExplicitValueCPA(ConfigurableProgramAnalysis):
    """CPA component tracking explicit integer values for known variables."""

    def __init__(self, variables: Iterable[str]):
        self._variables = tuple(sorted(set(variables)))
        self._domain = ExplicitValueDomain()
        self._transfer = ExplicitValueTransferRelation()
        self._merge = SepMergeOperator()
        self._stop = ExactStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> ExplicitValueState:
        del node_id
        return ExplicitValueState().retain(self._variables)

    def get_initial_precision(self) -> Precision:
        return TRIVIAL_PRECISION


@dataclass(frozen=True)
class CompositeState(AbstractState):
    """Product state combining multiple CPA component states."""

    components: tuple[AbstractState, ...]

    @property
    def location(self) -> int:
        return extract_location(self)

    def __repr__(self) -> str:
        return f"CompositeState({', '.join(repr(c) for c in self.components)})"


class CompositeDomain(AbstractDomain):
    def __init__(self, domains: Iterable[AbstractDomain]):
        self._domains = tuple(domains)

    def is_less_or_equal(self, state1: CompositeState, state2: CompositeState) -> bool:
        return all(
            domain.is_less_or_equal(component1, component2)
            for domain, component1, component2 in zip(
                self._domains, state1.components, state2.components
            )
        )

    def join(self, state1: CompositeState, state2: CompositeState) -> CompositeState:
        return CompositeState(
            tuple(
                domain.join(component1, component2)
                for domain, component1, component2 in zip(
                    self._domains, state1.components, state2.components
                )
            )
        )

    def get_top(self) -> CompositeState:
        return CompositeState(tuple(domain.get_top() for domain in self._domains))

    def get_bottom(self) -> CompositeState:
        return CompositeState(tuple(domain.get_bottom() for domain in self._domains))

        return CompositeState(tuple(domain.get_bottom() for domain in self._domains))


class CompositeTransferRelation(TransferRelation):
    def __init__(self, transfers: Iterable[TransferRelation]):
        self._transfers = tuple(transfers)

    def get_abstract_successors(
        self, state: CompositeState, precision: Precision, edge: CFAEdge
    ) -> list[CompositeState]:
        successor_lists = [
            transfer.get_abstract_successors(component, precision, edge)
            for transfer, component in zip(self._transfers, state.components)
        ]
        return [
            CompositeState(tuple(components))
            for components in product(*successor_lists)
        ]


class CompositeMergeOperator(MergeOperator):
    def __init__(self, merges: Iterable[MergeOperator]):
        self._merges = tuple(merges)

    def merge(
        self, state1: CompositeState, state2: CompositeState, precision: Precision
    ) -> CompositeState:
        return CompositeState(
            tuple(
                merge.merge(component1, component2, precision)
                for merge, component1, component2 in zip(
                    self._merges, state1.components, state2.components
                )
            )
        )


class CompositeStopOperator(StopOperator):
    def __init__(self, domain: CompositeDomain):
        self._domain = domain

    def stop(
        self, state: CompositeState, reached: set[CompositeState], precision: Precision
    ) -> bool:
        del precision
        return any(self._domain.is_less_or_equal(state, other) for other in reached)


class CompositeCPA(ConfigurableProgramAnalysis):
    """Product CPA over a list of CPA components."""

    def __init__(self, cpas: Iterable[ConfigurableProgramAnalysis]):
        self._cpas = tuple(cpas)
        self._domain = CompositeDomain(cpa.get_abstract_domain() for cpa in self._cpas)
        self._transfer = CompositeTransferRelation(
            cpa.get_transfer_relation() for cpa in self._cpas
        )
        self._merge = CompositeMergeOperator(
            cpa.get_merge_operator() for cpa in self._cpas
        )
        self._stop = CompositeStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> CompositeState:
        return CompositeState(
            tuple(cpa.get_initial_state(node_id) for cpa in self._cpas)
        )

    def get_initial_precision(self) -> Precision:
        return TRIVIAL_PRECISION


def extract_location(state: AbstractState) -> int:
    """Extract the CFA location stored in a location or composite state."""

    if isinstance(state, LocationState):
        return state.node_id
    if isinstance(state, CompositeState):
        for component in state.components:
            try:
                return extract_location(component)
            except TypeError:
                continue
    raise TypeError(f"State {state!r} does not contain a location component")


class CPAAlgorithm:
    """Generic worklist reachability algorithm for CPAs."""

    def __init__(self, cfa: CFA, cpa: ConfigurableProgramAnalysis, timelimit: int):
        self._cfa = cfa
        self._cpa = cpa
        self._timelimit = timelimit

    def run(self) -> VerificationResult:
        start_time = time.time()
        precision = self._cpa.get_initial_precision()
        transfer = self._cpa.get_transfer_relation()
        merge = self._cpa.get_merge_operator()
        stop = self._cpa.get_stop_operator()

        initial_state = self._cpa.get_initial_state(self._cfa.entry_node)
        worklist: deque[AbstractState] = deque([initial_state])
        reached: set[AbstractState] = {initial_state}
        reached_by_location: dict[int, set[AbstractState]] = defaultdict(set)
        reached_by_location[extract_location(initial_state)].add(initial_state)
        parents: dict[AbstractState, tuple[AbstractState, CFAEdge]] = {}

        iterations = 0
        expanded_states = 0
        max_worklist_size = 1

        while worklist:
            if time.time() - start_time > self._timelimit:
                return VerificationResult(
                    verdict=Verdict.UNKNOWN,
                    statistics={
                        "iterations": iterations,
                        "expanded_states": expanded_states,
                        "reached_states": len(reached),
                        "max_worklist_size": max_worklist_size,
                        "timeout": True,
                    },
                )

            state = worklist.popleft()
            iterations += 1
            location = extract_location(state)

            if self._cfa.nodes[location].is_error:
                error_path = reconstruct_error_path(state, parents)
                return VerificationResult(
                    verdict=Verdict.FALSE,
                    property_violated="assertion",
                    error_path=error_path,
                    statistics={
                        "iterations": iterations,
                        "expanded_states": expanded_states,
                        "reached_states": len(reached),
                        "max_worklist_size": max_worklist_size,
                    },
                )

            for edge in self._cfa.get_successors(location):
                successors = transfer.get_abstract_successors(state, precision, edge)
                if not successors:
                    continue
                expanded_states += 1

                for successor in successors:
                    successor_location = extract_location(successor)
                    local_reached = reached_by_location[successor_location]
                    current_successor = successor

                    for existing in list(local_reached):
                        merged = merge.merge(current_successor, existing, precision)
                        if merged == existing:
                            continue
                        reached.remove(existing)
                        local_reached.remove(existing)
                        reached.add(merged)
                        local_reached.add(merged)
                        if existing in worklist:
                            worklist = deque(
                                merged if candidate == existing else candidate
                                for candidate in worklist
                            )
                        current_successor = merged

                    if stop.stop(current_successor, local_reached, precision):
                        continue

                    if current_successor not in reached:
                        reached.add(current_successor)
                        local_reached.add(current_successor)
                        parents[current_successor] = (state, edge)
                    elif current_successor not in parents:
                        parents[current_successor] = (state, edge)

                    if self._cfa.nodes[successor_location].is_error:
                        error_path = reconstruct_error_path(current_successor, parents)
                        return VerificationResult(
                            verdict=Verdict.FALSE,
                            property_violated="assertion",
                            error_path=error_path,
                            statistics={
                                "iterations": iterations,
                                "expanded_states": expanded_states,
                                "reached_states": len(reached),
                                "max_worklist_size": max_worklist_size,
                            },
                        )

                    worklist.append(current_successor)
                    max_worklist_size = max(max_worklist_size, len(worklist))

        return VerificationResult(
            verdict=Verdict.TRUE,
            statistics={
                "iterations": iterations,
                "expanded_states": expanded_states,
                "reached_states": len(reached),
                "max_worklist_size": max_worklist_size,
            },
        )


def reconstruct_error_path(
    state: AbstractState, parents: dict[AbstractState, tuple[AbstractState, CFAEdge]]
) -> list[dict[str, object]]:
    """Build a simple counterexample path from the stored parent map."""

    path: list[dict[str, object]] = []
    current = state
    while current in parents:
        parent, edge = parents[current]
        path.append(
            {
                "source": extract_location(parent),
                "target": extract_location(current),
                "edge_type": edge.edge_type.value,
                "expression": edge.expression,
                "variable": edge.variable,
            }
        )
        current = parent
    path.reverse()
    return path


def run_value_analysis(cfa: CFA, timelimit: int) -> VerificationResult:
    """Run explicit-value analysis over the given CFA."""

    cpa = CompositeCPA([LocationCPA(), ExplicitValueCPA(cfa.variables)])
    return CPAAlgorithm(cfa, cpa, timelimit).run()

"""Predicate analysis with lightweight path feasibility checking."""

from __future__ import annotations

from dataclasses import dataclass

from cpachecker.analyses.symbolic import (
    Constraint,
    PathFeasibilityChecker,
    Satisfiability,
    assignment_constraint,
    invert_self_update,
    negate_constraint,
    parse_constraint,
    parse_expression,
)
from cpachecker.analyses.value_analysis import (
    CPAAlgorithm,
    CompositeCPA,
    LocationCPA,
    SepMergeOperator,
    TRIVIAL_PRECISION,
)
from cpachecker.cfa import CFA, CFAEdge, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.expression import is_nondeterministic
from cpachecker.result import VerificationResult


@dataclass(frozen=True)
class PredicateAbstractState(AbstractState):
    """Predicate state represented as a normalized set of constraints."""

    predicates: frozenset[Constraint] = frozenset()

    @property
    def semantic_keys(self) -> frozenset[tuple[object, ...]]:
        return frozenset(predicate.semantic_key() for predicate in self.predicates)

    def __repr__(self) -> str:
        return f"PredicateAbstractState({sorted(self.semantic_keys)!r})"


class PredicateDomain(AbstractDomain):
    def is_less_or_equal(
        self, state1: PredicateAbstractState, state2: PredicateAbstractState
    ) -> bool:
        return state2.semantic_keys.issubset(state1.semantic_keys)

    def join(
        self, state1: PredicateAbstractState, state2: PredicateAbstractState
    ) -> PredicateAbstractState:
        common_keys = state1.semantic_keys & state2.semantic_keys
        chosen = {
            predicate
            for predicate in state1.predicates | state2.predicates
            if predicate.semantic_key() in common_keys
        }
        return PredicateAbstractState(frozenset(chosen))

    def get_top(self) -> PredicateAbstractState:
        return PredicateAbstractState()

    def get_bottom(self) -> PredicateAbstractState:
        return PredicateAbstractState(frozenset())


class PredicateTransferRelation(TransferRelation):
    def __init__(self, checker: PathFeasibilityChecker):
        self._checker = checker

    def get_abstract_successors(
        self, state: PredicateAbstractState, precision: Precision, edge: CFAEdge
    ) -> list[PredicateAbstractState]:
        del precision
        if edge.edge_type == EdgeType.ASSIGNMENT:
            return self._assignment_successor(state, edge)

        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            constraint = parse_constraint(edge.expression)
            if edge.edge_type == EdgeType.ASSUME_FALSE:
                constraint = negate_constraint(constraint)
            status, normalized = self._checker.normalize((*state.predicates, constraint))
            if status == Satisfiability.UNSAT:
                return []
            return [PredicateAbstractState(normalized)]

        if edge.edge_type in (EdgeType.BLANK, EdgeType.FUNCTION_CALL, EdgeType.ASSERT):
            return [state]

        return [state]

    def _assignment_successor(
        self, state: PredicateAbstractState, edge: CFAEdge
    ) -> list[PredicateAbstractState]:
        surviving: list[Constraint] = []

        if is_nondeterministic(edge.expression):
            for predicate in state.predicates:
                if not predicate.mentions(edge.variable):
                    surviving.append(predicate)
            status, normalized = self._checker.normalize(surviving)
            if status == Satisfiability.UNSAT:
                return []
            return [PredicateAbstractState(normalized)]

        expr = parse_expression(edge.expression)
        inverse = invert_self_update(edge.variable, expr)

        for predicate in state.predicates:
            if not predicate.mentions(edge.variable):
                surviving.append(predicate)
                continue
            if inverse is None:
                continue
            surviving.append(predicate.substitute(edge.variable, inverse))

        definition = assignment_constraint(edge.variable, expr)
        if definition is not None:
            surviving.append(definition)

        status, normalized = self._checker.normalize(surviving)
        if status == Satisfiability.UNSAT:
            return []
        return [PredicateAbstractState(normalized)]


class PredicateStopOperator(StopOperator):
    def __init__(self, domain: PredicateDomain):
        self._domain = domain

    def stop(
        self, state: PredicateAbstractState, reached: set[PredicateAbstractState], precision: Precision
    ) -> bool:
        del precision
        return any(self._domain.is_less_or_equal(state, other) for other in reached)


class PredicateCPA(ConfigurableProgramAnalysis):
    """CPA component for symbolic predicate tracking."""

    def __init__(self):
        self._checker = PathFeasibilityChecker()
        self._domain = PredicateDomain()
        self._transfer = PredicateTransferRelation(self._checker)
        self._merge = SepMergeOperator()
        self._stop = PredicateStopOperator(self._domain)

    @property
    def checker(self) -> PathFeasibilityChecker:
        return self._checker

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> PredicateAbstractState:
        del node_id
        return PredicateAbstractState()

    def get_initial_precision(self) -> Precision:
        return TRIVIAL_PRECISION


def run_predicate_analysis(cfa: CFA, timelimit: int) -> VerificationResult:
    """Run predicate analysis over the given CFA."""

    cpa = CompositeCPA([LocationCPA(), PredicateCPA()])
    return CPAAlgorithm(cfa, cpa, timelimit).run()

"""Symbolic arithmetic helpers and a lightweight feasibility checker."""

from __future__ import annotations

import ast
import itertools
import re
from dataclasses import dataclass
from enum import Enum
from functools import lru_cache
from typing import Iterable


_SUFFIX_RE = re.compile(r"\b(\d+)[UuLl]+\b")
_NOT_RE = re.compile(r"(?<![<>=!])!(?!=)")


class Satisfiability(Enum):
    SAT = "SAT"
    UNSAT = "UNSAT"


@dataclass(frozen=True)
class Expr:
    """Base marker for arithmetic expression nodes."""


@dataclass(frozen=True)
class Constant(Expr):
    value: int


@dataclass(frozen=True)
class Variable(Expr):
    name: str


@dataclass(frozen=True)
class UnaryOp(Expr):
    op: str
    operand: Expr


@dataclass(frozen=True)
class BinaryOp(Expr):
    op: str
    left: Expr
    right: Expr


def _clean_expression(source: str) -> str:
    cleaned = source.strip()
    cleaned = _SUFFIX_RE.sub(r"\1", cleaned)
    cleaned = cleaned.replace("&&", " and ").replace("||", " or ")
    cleaned = _NOT_RE.sub(" not ", cleaned)
    return cleaned


@lru_cache(maxsize=512)
def parse_expression(source: str) -> Expr:
    """Parse an arithmetic expression into a tiny immutable AST."""

    node = ast.parse(_clean_expression(source), mode="eval").body
    return _convert_expr(node)


def _convert_expr(node: ast.AST) -> Expr:
    if isinstance(node, ast.Constant) and isinstance(node.value, int):
        return Constant(int(node.value))
    if isinstance(node, ast.Name):
        return Variable(node.id)
    if isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.USub):
            return UnaryOp("-", _convert_expr(node.operand))
        if isinstance(node.op, ast.UAdd):
            return _convert_expr(node.operand)
    if isinstance(node, ast.BinOp):
        left = _convert_expr(node.left)
        right = _convert_expr(node.right)
        if isinstance(node.op, ast.Add):
            return BinaryOp("+", left, right)
        if isinstance(node.op, ast.Sub):
            return BinaryOp("-", left, right)
        if isinstance(node.op, ast.Mult):
            return BinaryOp("*", left, right)
        if isinstance(node.op, ast.Mod):
            return BinaryOp("%", left, right)
        if isinstance(node.op, ast.FloorDiv):
            return BinaryOp("//", left, right)
    raise ValueError(f"Unsupported expression node: {ast.dump(node)}")


def expr_contains(expr: Expr, variable: str) -> bool:
    if isinstance(expr, Variable):
        return expr.name == variable
    if isinstance(expr, Constant):
        return False
    if isinstance(expr, UnaryOp):
        return expr_contains(expr.operand, variable)
    return expr_contains(expr.left, variable) or expr_contains(expr.right, variable)


def simplify_expr(expr: Expr) -> Expr:
    """Simplify arithmetic expressions by constant folding and identity removal."""

    if isinstance(expr, (Constant, Variable)):
        return expr

    if isinstance(expr, UnaryOp):
        operand = simplify_expr(expr.operand)
        if isinstance(operand, Constant):
            return Constant(-operand.value)
        if isinstance(operand, UnaryOp) and operand.op == "-":
            return simplify_expr(operand.operand)
        return UnaryOp(expr.op, operand)

    left = simplify_expr(expr.left)
    right = simplify_expr(expr.right)

    if isinstance(left, Constant) and isinstance(right, Constant):
        if expr.op == "+":
            return Constant(left.value + right.value)
        if expr.op == "-":
            return Constant(left.value - right.value)
        if expr.op == "*":
            return Constant(left.value * right.value)
        if expr.op == "%" and right.value != 0:
            return Constant(left.value % right.value)
        if expr.op == "//" and right.value != 0:
            return Constant(left.value // right.value)

    if expr.op == "+":
        if isinstance(left, Constant) and left.value == 0:
            return right
        if isinstance(right, Constant) and right.value == 0:
            return left
    if expr.op == "-":
        if isinstance(right, Constant) and right.value == 0:
            return left
        if isinstance(left, Constant) and left.value == 0:
            return simplify_expr(UnaryOp("-", right))
    if expr.op == "*":
        if isinstance(left, Constant):
            if left.value == 0:
                return Constant(0)
            if left.value == 1:
                return right
        if isinstance(right, Constant):
            if right.value == 0:
                return Constant(0)
            if right.value == 1:
                return left
    if expr.op == "%" and isinstance(right, Constant) and right.value == 1:
        return Constant(0)

    return BinaryOp(expr.op, left, right)


def substitute_expr(expr: Expr, variable: str, replacement: Expr) -> Expr:
    if isinstance(expr, Constant):
        return expr
    if isinstance(expr, Variable):
        return replacement if expr.name == variable else expr
    if isinstance(expr, UnaryOp):
        return simplify_expr(UnaryOp(expr.op, substitute_expr(expr.operand, variable, replacement)))
    return simplify_expr(
        BinaryOp(
            expr.op,
            substitute_expr(expr.left, variable, replacement),
            substitute_expr(expr.right, variable, replacement),
        )
    )


def evaluate_expr(expr: Expr, env: dict[str, int]) -> int | None:
    if isinstance(expr, Constant):
        return expr.value
    if isinstance(expr, Variable):
        return env.get(expr.name)
    if isinstance(expr, UnaryOp):
        value = evaluate_expr(expr.operand, env)
        return None if value is None else -value
    left = evaluate_expr(expr.left, env)
    right = evaluate_expr(expr.right, env)
    if left is None or right is None:
        return None
    if expr.op == "+":
        return left + right
    if expr.op == "-":
        return left - right
    if expr.op == "*":
        return left * right
    if expr.op == "%" and right != 0:
        return left % right
    if expr.op == "//" and right != 0:
        return left // right
    return None


@dataclass(frozen=True)
class LinearForm:
    """Normalized linear arithmetic expression."""

    coefficients: tuple[tuple[str, int], ...] = ()
    constant: int = 0

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "coefficients",
            tuple(sorted((var, coeff) for var, coeff in self.coefficients if coeff != 0)),
        )

    @staticmethod
    def constant_form(value: int) -> "LinearForm":
        return LinearForm((), int(value))

    @staticmethod
    def variable(name: str, coeff: int = 1) -> "LinearForm":
        return LinearForm(((name, coeff),), 0)

    @property
    def variables(self) -> tuple[str, ...]:
        return tuple(var for var, _ in self.coefficients)

    def coefficient(self, variable: str) -> int:
        for var, coeff in self.coefficients:
            if var == variable:
                return coeff
        return 0

    def is_constant(self) -> bool:
        return not self.coefficients

    def add(self, other: "LinearForm") -> "LinearForm":
        coeffs: dict[str, int] = dict(self.coefficients)
        for var, coeff in other.coefficients:
            coeffs[var] = coeffs.get(var, 0) + coeff
        return LinearForm(tuple(coeffs.items()), self.constant + other.constant)

    def sub(self, other: "LinearForm") -> "LinearForm":
        return self.add(other.scale(-1))

    def scale(self, factor: int) -> "LinearForm":
        return LinearForm(
            tuple((var, coeff * factor) for var, coeff in self.coefficients),
            self.constant * factor,
        )

    def without(self, variable: str) -> "LinearForm":
        return LinearForm(
            tuple((var, coeff) for var, coeff in self.coefficients if var != variable),
            self.constant,
        )

    def substitute(self, variable: str, replacement: "LinearForm") -> "LinearForm":
        coeff = self.coefficient(variable)
        if coeff == 0:
            return self
        base = self.without(variable)
        return base.add(replacement.scale(coeff))

    def evaluate(self, env: dict[str, int]) -> int | None:
        total = self.constant
        for var, coeff in self.coefficients:
            if var not in env:
                return None
            total += coeff * env[var]
        return total

    def bounds(self) -> tuple[int | None, int | None]:
        if len(self.coefficients) != 1:
            return None, None
        variable, coeff = self.coefficients[0]
        del variable
        if coeff == 1:
            return -self.constant, -self.constant
        if coeff == -1:
            return self.constant, self.constant
        return None, None

    def as_expr(self) -> Expr:
        expr: Expr = Constant(self.constant)
        for variable, coeff in self.coefficients:
            term: Expr = Variable(variable)
            if coeff != 1:
                term = BinaryOp("*", Constant(coeff), term)
            expr = BinaryOp("+", expr, term)
        return simplify_expr(expr)


def to_linear_form(expr: Expr) -> LinearForm | None:
    expr = simplify_expr(expr)
    if isinstance(expr, Constant):
        return LinearForm.constant_form(expr.value)
    if isinstance(expr, Variable):
        return LinearForm.variable(expr.name)
    if isinstance(expr, UnaryOp):
        operand = to_linear_form(expr.operand)
        return operand.scale(-1) if operand is not None else None
    if isinstance(expr, BinaryOp):
        left = to_linear_form(expr.left)
        right = to_linear_form(expr.right)
        if expr.op == "+" and left is not None and right is not None:
            return left.add(right)
        if expr.op == "-" and left is not None and right is not None:
            return left.sub(right)
        if expr.op == "*":
            if isinstance(expr.left, Constant) and right is not None:
                return right.scale(expr.left.value)
            if isinstance(expr.right, Constant) and left is not None:
                return left.scale(expr.right.value)
    return None


@dataclass(frozen=True)
class LinearConstraint:
    """Linear relation of the form form op 0."""

    form: LinearForm

    form: LinearForm
    op: str
    origin_var: str | None = None

    def semantic_key(self) -> tuple[object, ...]:
        return ("linear", self.form, self.op)

    def variables(self) -> tuple[str, ...]:
        return self.form.variables

    def mentions(self, variable: str) -> bool:
        return variable in self.variables()

    def substitute(self, variable: str, replacement: LinearForm) -> "LinearConstraint":
        return canonicalize_linear_constraint(
            LinearConstraint(self.form.substitute(variable, replacement), self.op, self.origin_var)
        )

    def as_definition(self) -> tuple[str, LinearForm] | None:
        if self.op != "==" or self.origin_var is None:
            return None
        coeff = self.form.coefficient(self.origin_var)
        if coeff not in (1, -1):
            return None
        rest = self.form.without(self.origin_var)
        if coeff == 1:
            return self.origin_var, rest.scale(-1)
        return self.origin_var, rest

    def evaluate(self, env: dict[str, int]) -> bool | None:
        value = self.form.evaluate(env)
        if value is None:
            return None
        return _compare(value, self.op, 0)


@dataclass(frozen=True)
class ModuloConstraint:
    """Constraint of the form (form % modulus) op rhs."""

    form: LinearForm
    modulus: int
    op: str
    rhs: int
    origin_var: str | None = None

    def semantic_key(self) -> tuple[object, ...]:
        return ("mod", self.form, self.modulus, self.op, self.rhs)

    def variables(self) -> tuple[str, ...]:
        return self.form.variables

    def mentions(self, variable: str) -> bool:
        return variable in self.variables()

    def substitute(self, variable: str, replacement: LinearForm) -> "ModuloConstraint":
        return canonicalize_modulo_constraint(
            ModuloConstraint(
                self.form.substitute(variable, replacement),
                self.modulus,
                self.op,
                self.rhs,
                self.origin_var,
            )
        )

    def evaluate(self, env: dict[str, int]) -> bool | None:
        value = self.form.evaluate(env)
        if value is None or self.modulus == 0:
            return None
        return _compare(value % self.modulus, self.op, self.rhs)


Constraint = LinearConstraint | ModuloConstraint


def canonicalize_linear_constraint(constraint: LinearConstraint) -> LinearConstraint:
    form = constraint.form
    op = constraint.op
    if form.coefficients:
        first_coeff = form.coefficients[0][1]
        if first_coeff < 0:
            form = form.scale(-1)
            op = _flip_direction(op)
    return LinearConstraint(form, op, constraint.origin_var)


def canonicalize_modulo_constraint(constraint: ModuloConstraint) -> ModuloConstraint:
    rhs = constraint.rhs
    modulus = abs(constraint.modulus)
    if modulus == 0:
        return constraint
    if constraint.op in ("==", "!="):
        rhs %= modulus
    form = constraint.form
    if form.coefficients:
        first_coeff = form.coefficients[0][1]
        if first_coeff < 0:
            form = form.scale(-1)
    return ModuloConstraint(form, modulus, constraint.op, rhs, constraint.origin_var)


def simplify_constraint(constraint: Constraint) -> Constraint | bool:
    if isinstance(constraint, LinearConstraint):
        simplified = canonicalize_linear_constraint(constraint)
        if simplified.form.is_constant():
            return _compare(simplified.form.constant, simplified.op, 0)
        return simplified

    simplified = canonicalize_modulo_constraint(constraint)
    if simplified.form.is_constant():
        if simplified.modulus == 0:
            return False
        return _compare(simplified.form.constant % simplified.modulus, simplified.op, simplified.rhs)
    return simplified


def negate_constraint(constraint: Constraint) -> Constraint:
    negated = _negate_operator(constraint.op)
    if isinstance(constraint, LinearConstraint):
        return LinearConstraint(constraint.form, negated, constraint.origin_var)
    return ModuloConstraint(
        constraint.form,
        constraint.modulus,
        negated,
        constraint.rhs,
        constraint.origin_var,
    )


@lru_cache(maxsize=512)
def parse_constraint(source: str) -> Constraint:
    """Parse a comparison expression into a symbolic constraint."""

    node = ast.parse(_clean_expression(source), mode="eval").body
    if not isinstance(node, ast.Compare) or len(node.ops) != 1 or len(node.comparators) != 1:
        raise ValueError(f"Unsupported predicate expression: {source}")

    left_expr = _convert_expr(node.left)
    right_expr = _convert_expr(node.comparators[0])
    op = _ast_compare_to_string(node.ops[0])

    if isinstance(left_expr, BinaryOp) and left_expr.op == "%" and isinstance(left_expr.right, Constant):
        form = to_linear_form(left_expr.left)
        right_value = evaluate_expr(right_expr, {})
        if form is not None and right_value is not None:
            return canonicalize_modulo_constraint(
                ModuloConstraint(form, left_expr.right.value, op, right_value)
            )

    left_form = to_linear_form(left_expr)
    right_form = to_linear_form(right_expr)
    if left_form is not None and right_form is not None:
        return canonicalize_linear_constraint(
            LinearConstraint(left_form.sub(right_form), op)
        )

    raise ValueError(f"Unsupported predicate expression: {source}")


def assignment_constraint(variable: str, expr: Expr) -> LinearConstraint | None:
    """Build a defining equality for a non-self linear assignment."""

    if expr_contains(expr, variable):
        return None
    form = to_linear_form(expr)
    if form is None:
        return None
    return canonicalize_linear_constraint(
        LinearConstraint(LinearForm.variable(variable).sub(form), "==", origin_var=variable)
    )


def invert_self_update(variable: str, expr: Expr) -> LinearForm | None:
    """Return the old-value substitution for assignments like x = x + c."""

    form = to_linear_form(expr)
    if form is None:
        return None
    coeff = form.coefficient(variable)
    other_vars = [var for var in form.variables if var != variable]
    if other_vars:
        return None
    if coeff == 1:
        return LinearForm.variable(variable).sub(LinearForm.constant_form(form.constant))
    if coeff == -1:
        return LinearForm.constant_form(form.constant).sub(LinearForm.variable(variable))
    return None


class PathFeasibilityChecker:
    """A lightweight satisfiability checker for linear arithmetic predicates."""

    def normalize(self, constraints: Iterable[Constraint]) -> tuple[Satisfiability, frozenset[Constraint]]:
        items: list[Constraint] = []
        for constraint in constraints:
            simplified = simplify_constraint(constraint)
            if simplified is False:
                return Satisfiability.UNSAT, frozenset()
            if simplified is True:
                continue
            items.append(simplified)

        changed = True
        while changed:
            changed = False
            substitutions = self._definitions(items)
            new_items: list[Constraint] = []
            for constraint in items:
                updated = constraint
                for variable, replacement in substitutions.items():
                    if isinstance(updated, LinearConstraint) and updated.origin_var == variable:
                        continue
                    if isinstance(updated, ModuloConstraint) and updated.origin_var == variable:
                        continue
                    if variable not in updated.variables():
                        continue
                    updated = updated.substitute(variable, replacement)
                simplified = simplify_constraint(updated)
                if simplified is False:
                    return Satisfiability.UNSAT, frozenset()
                if simplified is True:
                    changed = True
                    continue
                if simplified != constraint:
                    changed = True
                new_items.append(simplified)
            items = self._deduplicate(new_items)

        if self._contradiction(items):
            return Satisfiability.UNSAT, frozenset()
        return Satisfiability.SAT, frozenset(items)

    def is_satisfiable(self, constraints: Iterable[Constraint]) -> bool:
        status, _ = self.normalize(constraints)
        return status == Satisfiability.SAT

    def find_model(self, constraints: Iterable[Constraint], search_limit: int = 12) -> dict[str, int] | None:
        status, normalized = self.normalize(constraints)
        if status == Satisfiability.UNSAT:
            return None

        variables = sorted({var for constraint in normalized for var in constraint.variables()})
        if not variables:
            return {}

        lower_bounds, upper_bounds = self._bounds(normalized)
        domains = [
            range(
                max(lower_bounds.get(var, -search_limit), -search_limit),
                min(upper_bounds.get(var, search_limit), search_limit) + 1,
            )
            for var in variables
        ]
        for values in itertools.product(*domains):
            env = dict(zip(variables, values))
            if all(constraint.evaluate(env) is True for constraint in normalized):
                return env
        return None

    def _definitions(self, constraints: Iterable[Constraint]) -> dict[str, LinearForm]:
        substitutions: dict[str, LinearForm] = {}
        for constraint in constraints:
            if not isinstance(constraint, LinearConstraint):
                continue
            definition = constraint.as_definition()
            if definition is None:
                continue
            variable, replacement = definition
            if variable in replacement.variables:
                continue
            substitutions.setdefault(variable, replacement)
        return substitutions

    def _deduplicate(self, constraints: Iterable[Constraint]) -> list[Constraint]:
        dedup: dict[tuple[object, ...], Constraint] = {}
        for constraint in constraints:
            key = constraint.semantic_key()
            existing = dedup.get(key)
            if existing is None or getattr(constraint, "origin_var", None) is not None:
                dedup[key] = constraint
        return list(dedup.values())

    def _contradiction(self, constraints: Iterable[Constraint]) -> bool:
        linear_by_key: dict[tuple[object, ...], set[str]] = {}
        for constraint in constraints:
            if isinstance(constraint, LinearConstraint):
                linear_by_key.setdefault(("linear", constraint.form), set()).add(constraint.op)
            elif isinstance(constraint, ModuloConstraint):
                if constraint.op == "==" and constraint.rhs % constraint.modulus != constraint.rhs and constraint.modulus != 0:
                    return True

        for _, ops in linear_by_key.items():
            if "==" in ops and "!=" in ops:
                return True

        lower_bounds, upper_bounds = self._bounds(constraints)
        return any(lower_bounds[var] > upper_bounds[var] for var in lower_bounds.keys() & upper_bounds.keys())

    def _bounds(self, constraints: Iterable[Constraint]) -> tuple[dict[str, int], dict[str, int]]:
        lower: dict[str, int] = {}
        upper: dict[str, int] = {}

        for constraint in constraints:
            if not isinstance(constraint, LinearConstraint):
                continue
            if len(constraint.form.coefficients) != 1:
                continue
            variable, coeff = constraint.form.coefficients[0]
            const = constraint.form.constant

            if coeff == 1:
                if constraint.op == "==":
                    bound = -const
                    lower[variable] = max(lower.get(variable, bound), bound)
                    upper[variable] = min(upper.get(variable, bound), bound)
                elif constraint.op == ">=":
                    lower[variable] = max(lower.get(variable, -10**9), -const)
                elif constraint.op == ">":
                    lower[variable] = max(lower.get(variable, -10**9), -const + 1)
                elif constraint.op == "<=":
